CREATE TABLE accounts (
 id INTEGER PRIMARY KEY,
 owner TEXT NOT NULL,
 cents INTEGER NOT NULL CHECK(cents >= 0)
);

SELECT id, cents FROM accounts
WHERE owner = ? AND id = ?
ORDER BY id;

BEGIN;
UPDATE accounts SET cents=cents-500 WHERE id=1;
UPDATE accounts SET cents=cents+500 WHERE id=2;
COMMIT;

