visiting = set()
visited = set()
def visit(node):
    if node in visiting: raise ValueError("cycle")
    if node in visited: return
    visiting.add(node)
    for parent in deps[node]: visit(parent)
    visiting.remove(node)
    visited.add(node)

def cents(amount: int) -> int:
    if type(amount) is not int or amount <= 0: raise ValueError("amount")
    return amount

def delays():
    for attempt in range(3):
        yield min(8, 2 ** attempt)
assert list(delays())==[1,2,4]

